const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const markets={ETH:{name:'Ethereum',price:2648.32,high:2712.6,low:2531.18,icon:'Ξ'},BTC:{name:'Bitcoin',price:64218.75,high:65410.2,low:62104.3,icon:'₿'},SOL:{name:'Solana',price:148.62,high:153.1,low:142.45,icon:'◎'}};
let state={connected:false,balances:{USDC:10000,ETH:1,BTC:.02,SOL:10},orders:[],history:[]};try{const saved=JSON.parse(localStorage.getItem('flux-demo-v1'));if(saved&&saved.balances&&Array.isArray(saved.orders)&&Array.isArray(saved.history))state=saved}catch{}
let symbol='ETH',side='buy',type='market',tab='orders',period='1H';const fmt=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});const save=()=>{try{localStorage.setItem('flux-demo-v1',JSON.stringify(state))}catch{}};let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function table(head,rows){return `<table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`}
function refresh(){const m=markets[symbol];$('#asset-name').textContent=m.name;$('.coin').textContent=m.icon;$('#price').textContent='$'+fmt(m.price);$('#high').textContent=fmt(m.high);$('#low').textContent=fmt(m.low);$('#book-price').textContent=fmt(m.price)+' ↑';$$('.symbol').forEach(e=>e.textContent=symbol);$('#wallet').textContent=state.connected?'◈ Demo account':'◈ Start demo';$('#available').textContent=state.connected?fmt(state.balances[side==='buy'?'USDC':symbol],side==='buy'?2:4)+' '+(side==='buy'?'USDC':symbol):'— USDC';$('#submit').innerHTML=state.connected?`${side==='buy'?'Buy':'Sell'} ${symbol} <span>→</span>`:'Start demo to trade <span>→</span>';$('#order-count').textContent=state.orders.length;renderBook();cost();renderActivity();renderPortfolio();if(typeof refreshProducts==="function")refreshProducts()}
function cost(){const qty=Number($('#amount').value)||0,p=type==='limit'?Number($('#limit').value):markets[symbol].price;$('#value').textContent=fmt(qty*p)+' USDC';$('#fee').textContent=fmt(qty*p*.001)+' USDC'}
function renderBook(){['asks','bids'].forEach((id,k)=>{$('#'+id).innerHTML=Array.from({length:6},(_,i)=>{let n=k?i+1:6-i,p=markets[symbol].price+(k?-1:1)*n*markets[symbol].price*.00013,size=(Math.sin(i*3+1)+1.4)*2;return `<div class="book-row ${k?'bid':'ask'}" style="--width:${25+((i*17+22)%65)}%"><span>${fmt(p)}</span><span>${fmt(size,4)}</span><span>${fmt(p*size,0)}</span></div>`}).join('')})}
function chart(){let price=markets[symbol].price,seed=period.split('').reduce((a,c)=>a+c.charCodeAt(0),0);const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};let v=80,candles=[];for(let i=0;i<65;i++){const open=v;v=Math.max(30,Math.min(210,v+(rand()-.43)*24));candles.push({o:open,c:v,h:Math.max(v,open)+rand()*14,l:Math.min(v,open)-rand()*14,vol:rand()*34+6})}const last=candles.at(-1).c, y=v=>260-v;let svg='';for(let i=0;i<5;i++){const yy=34+i*54;svg+=`<line x1="0" y1="${yy}" x2="685" y2="${yy}" stroke="#2a302a" stroke-dasharray="3 5"/><text x="699" y="${yy+4}" fill="#7e8a7d" font-size="10" font-family="monospace">${fmt(price+(y(last)-yy)*price*.00015)}</text>`}candles.forEach((c,i)=>{const x=9+i*10.25,color=c.c>=c.o?'#95cea3':'#d98288';svg+=`<line x1="${x}" x2="${x}" y1="${y(c.h)}" y2="${y(c.l)}" stroke="${color}"/><rect x="${x-3}" y="${y(Math.max(c.o,c.c))}" width="6" height="${Math.max(1,Math.abs(c.o-c.c))}" fill="${color}" rx=".6"/><rect x="${x-3}" y="${332-c.vol}" width="6" height="${c.vol}" fill="${color}" opacity=".18"/>`});svg+=`<line x1="0" y1="${y(last)}" x2="690" y2="${y(last)}" stroke="#9ed88b" stroke-dasharray="4 4" opacity=".6"/><rect x="691" y="${y(last)-10}" width="69" height="21" fill="#344b2c" rx="3"/><text x="697" y="${y(last)+4}" fill="#c4f66b" font-size="10" font-family="monospace">${fmt(price)}</text>`;$('#chart').innerHTML=svg;$('#ohlc').textContent=`O ${fmt(price*.992)}   H ${fmt(price*1.009)}   L ${fmt(price*.987)}   C ${fmt(price)}   +3.42%`;const times={'15m':['15:00','15:15','15:30','15:45','16:00'],'1H':['08:00','10:00','12:00','14:00','16:00'],'4H':['00:00','04:00','08:00','12:00','16:00'],'1D':['Mon','Tue','Wed','Thu','Fri'],'1W':['Sep 07','Sep 14','Sep 21','Sep 28','Oct 05']};$('.chart-bottom').innerHTML=times[period].map(t=>`<span>${t}</span>`).join('')}
function balanceRows(){return Object.entries(state.balances).map(([asset,n])=>`<tr><td>${asset}</td><td>${fmt(n,asset==='USDC'?2:4)}</td><td>$${fmt(n*(asset==='ETH'?FluxEngine.init(state).mark:(markets[asset]?.price||1)))}</td></tr>`)}
function renderActivity(){let html;if(tab==='balances')html=table(['Asset','Available','Value (USDC)'],state.connected?balanceRows():[]);else {const data=tab==='orders'?state.orders:state.history;if(!data.length)html=`<div class="empty"><div class="empty-icon">▤</div>${tab==='orders'?'No open orders yet':'Your trading story starts here'}<p>${tab==='orders'?'Your active limit orders will appear here.':'Place a demo trade to see its settlement record.'}</p></div>`;else html=table(['Market / Side','Amount','Price','Status',tab==='orders'?'Action':'Time'],data.map(o=>`<tr><td>${o.symbol} <span class="${o.side==='buy'?'green':''}">${o.side}</span></td><td>${fmt(o.qty,4)}</td><td>${fmt(o.price)}</td><td>${tab==='orders'?'Open':'Settled · demo'}</td><td>${tab==='orders'?`<button data-cancel="${o.id}">Cancel</button>`:new Date(o.time).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</td></tr>`))}$('#activity-content').innerHTML=html;$$('[data-cancel]').forEach(b=>b.onclick=()=>cancel(b.dataset.cancel))}
function renderPortfolio(){let total=FluxEngine.extraValue(state)+Object.entries(state.balances).reduce((sum,[a,n])=>sum+n*(a==='ETH'?FluxEngine.init(state).mark:(markets[a]?.price||1)),0);state.orders.forEach(o=>total+=o.side==='buy'?o.reserved:o.qty*markets[o.symbol].price);$('#portfolio-content').innerHTML=state.connected?`<div class="balance-summary">$${fmt(total)}<p style="font:11px 'DM Sans'">Net practice value: assets + reserves + margin + vault − loan debt. ETH valued at the scenario mark.</p></div>`+table(['Asset','Available balance','Value'],balanceRows()):'<div class="empty">Start a demo account to explore your portfolio.<p>You receive 10,000 USDC and sample crypto balances.</p></div>'}
function connect(){state.connected=true;save();refresh();toast('Demo account ready. Your practice funds are available.')}
$('#wallet').onclick=()=>state.connected?toast('Demo account active — no real wallet connected.'):connect();$('#amount').oninput=cost;$('#limit').oninput=cost;
$$('[data-side]').forEach(b=>b.onclick=()=>{side=b.dataset.side;$$('[data-side]').forEach(x=>x.classList.toggle('selected',x===b));$('#error').textContent='';refresh()});$$('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;$$('[data-type]').forEach(x=>x.classList.toggle('active',x===b));$('#limit-wrap').hidden=type!=='limit';cost()});
$$('[data-percent]').forEach(b=>b.onclick=()=>{if(!state.connected){connect()}const p=type==='limit'?Number($('#limit').value):markets[symbol].price;if(!(p>0))return;const max=side==='buy'?state.balances.USDC/(p*1.001):state.balances[symbol];$('#amount').value=Math.floor(max*Number(b.dataset.percent)/100*1e6)/1e6;cost()});
function cancel(id){const o=state.orders.find(o=>o.id===id);if(!o)return;if(o.side==='buy')state.balances.USDC+=o.reserved;else state.balances[o.symbol]+=o.qty;state.orders=state.orders.filter(x=>x.id!==id);save();refresh();toast('Order cancelled. Reserved funds released.')}
$('#order-form').onsubmit=e=>{e.preventDefault();if(!state.connected){connect();return}const qty=Number($('#amount').value),limit=Number($('#limit').value),market=markets[symbol].price,p=type==='limit'?limit:market;$('#error').textContent='';if(!Number.isFinite(qty)||qty<.0001||!Number.isFinite(p)||p<=0){$('#error').textContent='Enter a valid amount and price.';return}const available=state.balances[side==='buy'?'USDC':symbol],needed=side==='buy'?qty*p*1.001:qty;if(needed>available+1e-9){$('#error').textContent='Insufficient available balance for this order and fee.';return}const crosses=type==='market'||(side==='buy'?limit>=market:limit<=market),executionPrice=crosses?market:p,o={id:crypto.randomUUID(),symbol,side,qty,price:executionPrice,time:Date.now(),reserved:needed};if(crosses){const gross=qty*executionPrice;if(side==='buy'){state.balances.USDC-=gross*1.001;state.balances[symbol]+=qty}else{state.balances[symbol]-=qty;state.balances.USDC+=gross*.999}state.history.unshift(o);$('#settle-status').textContent='Last trade settled · '+new Date().toLocaleTimeString();toast(`${side==='buy'?'Bought':'Sold'} ${fmt(qty,4)} ${symbol} · demo settlement complete`)}else{if(side==='buy')state.balances.USDC-=needed;else state.balances[symbol]-=qty;state.orders.unshift(o);toast('Limit order placed. Funds reserved.')}$('#amount').value='';save();refresh()};
$('#pair').onchange=()=>{symbol=$('#pair').value;$('#limit').value=(markets[symbol].price*.98).toFixed(2);$('#amount').value='';refresh();chart()};$$('#periods button').forEach(b=>b.onclick=()=>{period=b.textContent;$$('#periods button').forEach(x=>x.classList.toggle('selected',x===b));chart()});$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderActivity()});
function navigate(page){$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));['trade','markets','portfolio','perpetuals','lending','liquidity'].filter(p=>$('#'+p+'-page')).forEach(p=>$('#'+p+'-page').hidden=p!==page)}$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#market-table').innerHTML=table(['Market','Price','24h change',''],Object.entries(markets).map(([s,m])=>`<tr><td>${m.icon} &nbsp; ${m.name} <span style="color:#899483">${s}/USDC</span></td><td>$${fmt(m.price)}</td><td class="green">+3.42%</td><td><button data-market="${s}">Trade →</button></td></tr>`));$$('[data-market]').forEach(b=>b.onclick=()=>{$('#pair').value=b.dataset.market;$('#pair').onchange();navigate('trade')});$('#how').onclick=$('#docs').onclick=()=>$('#modal').showModal();$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};$('#reset').onclick=()=>{if(confirm('Reset all practice balances, orders, positions, loans, liquidity, and history?')){state={connected:false,balances:{USDC:10000,ETH:1,BTC:.02,SOL:10},orders:[],history:[]};save();refresh();$('#settle-status').textContent='Ready for your first trade';toast('Demo reset. Ready for a fresh start.')}};refresh();chart();
